import {PlusIcon} from '@primer/octicons-react'
import {Button} from '@primer/react'
import type React from 'react'
import {useRef, useState} from 'react'

import {McpServerDialog} from './McpServerDialog'

export interface ConfigureMcpServerPartialProps {}

export const ConfigureMcpServerPartial: React.FC<ConfigureMcpServerPartialProps> = () => {
  const [showDialog, setShowDialog] = useState(false)
  const buttonRef = useRef<HTMLButtonElement>(null)

  return (
    <>
      {/* New Tool Button */}
      <Button ref={buttonRef} size="small" leadingVisual={PlusIcon} onClick={() => setShowDialog(true)}>
        <strong>New tool</strong>
      </Button>

      {/* Dialog */}
      <McpServerDialog
        isOpen={showDialog}
        onClose={() => setShowDialog(false)}
        returnUrl="/settings/mcp" // Specific to MCP settings page
        returnFocusRef={buttonRef}
        showSettingsLink={false} // Don't show settings link when already in settings
      />
    </>
  )
}

try{ ConfigureMcpServerPartial.displayName ||= 'ConfigureMcpServerPartial' } catch {}